def solve(i,g):
    i=np.array(i); H,W=i.shape; mv=[v for v in np.unique(i) if v!=i.flat[0]][0]; bg=i.flat[0]
    pts=[(r,c) for r in range(H) for c in range(W) if i[r,c]==mv]
    grps={'row':collections.defaultdict(list),'col':collections.defaultdict(list),'d1':collections.defaultdict(list),'d2':collections.defaultdict(list)}
    for p in pts:
        grps['row'][p[0]].append(p); grps['col'][p[1]].append(p); grps['d1'][p[0]-p[1]].append(p); grps['d2'][p[0]+p[1]].append(p)
    pred=set()
    for name,grp in [('row',grps['row']),('col',grps['col']),('d1',grps['d1']),('d2',grps['d2'])]:
        for ps in grp.values():
            ps=sorted(ps)
            for a,b in zip(ps,ps[1:]):
                drn=(b[0]-a[0])//max(abs(b[0]-a[0]),abs(b[1]-a[1]))
                dcn=(b[1]-a[1])//max(abs(b[0]-a[0]),abs(b[1]-a[1]))
                n=max(abs(b[0]-a[0]),abs(b[1]-a[1]))
                s={(a[0]+drn*t,a[1]+dcn*t) for t in range(1,n)}-{a}
                pred|=s
    o=i.copy()
    for r in range(H):
        for c in range(W):
            if i[r,c]==bg and (r,c) in pred: o[r,c]=g
    return o.tolist()
for k in [1,2,3,4,5,6]:
